#!/usr/bin/env node
// SPIKE, referee only (booleans group, round 4 = critic round 2; the round-3 builder is frozen in booleans-r3/bool-build-rows-r3.round3.mjs). Rebuilds booleans.json from the recorded runs and ASSERTS every row's status against the cases it cites (exit 1 on any mismatch).
//   guarded runs : booleans-r4/guarded/cases/*.json   (run-booleans.mjs with BOOL_TR=guarded: bool-translate-r3.mjs + combine-exec.mjs + booleans.guard.mjs + booleans.slow.mjs = the contract), ALL non-fuzz cases of rounds 1-4
//   unguarded    : booleans-r3/r3raw/cases/*.json and booleans-r4/r3raw/cases/*.json     (BOOL_TR=r3raw: the same executor, NO guard)
//   as shipped   : booleans-raw-results.json (round 1) + booleans-r2/raw-*/cases/*.json + booleans-r3/phase0/cases + booleans-r4/phase0/cases   (the pristine phase0 translator, no guard)
//   others       : sliver-sweep.json, sliver-sweep-round.json, trap-hunt.json, trap-sweep.json, worker-browser.txt, probe-pieces.txt, census.json, fuzz-summary.json
//   bun contract/bool-build-rows-r3.mjs
// The status of a row is the status of its cases WITH the guard in front (that is the contract); the as-shipped / unguarded result is quoted next to it whenever it differs.
import { readFileSync, readdirSync, writeFileSync, existsSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { classify, shortOf, f3 } from './bool-classify-lib.mjs';
import * as GD from './booleans.guard.mjs';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const R2 = path.join(HERE, 'booleans-r2');
const R3 = path.join(HERE, 'booleans-r3');
const R4 = path.join(HERE, 'booleans-r4');
const readJ = (p) => JSON.parse(readFileSync(p, 'utf8'));
const loadDir = (base, d) => { const m = new Map(); const dir = path.join(base, d, 'cases'); if (existsSync(dir)) for (const f of readdirSync(dir)) { const r = readJ(path.join(dir, f)); m.set(r.id, r); } return m; };
const guarded = loadDir(R4, 'guarded');
const unguarded = loadDir(R3, 'r3raw'); for (const [k, v] of loadDir(R4, 'r3raw')) unguarded.set(k, v);
const shipped = new Map(); for (const r of readJ(path.join(HERE, 'booleans-raw-results.json'))) shipped.set(r.id, r);
for (const d of readdirSync(R2).filter((x) => /^raw-/.test(x))) for (const [k, v] of loadDir(R2, d)) shipped.set(k, v);
for (const [k, v] of loadDir(R3, 'phase0')) shipped.set(k, v);
for (const [k, v] of loadDir(R4, 'phase0')) shipped.set(k, v);
const timing = new Map(); for (const f of [path.join(HERE, 'booleans-timing.json'), path.join(R2, 'timing-sc.json')]) if (existsSync(f)) for (const t of readJ(f)) timing.set(t.id, t);

const CODE_OF = new Map();
for (const [k, fn] of Object.entries(GD.SENTENCES)) for (const op of ['union', 'subtract', 'intersect']) CODE_OF.set(k === 'skipped' ? 'skipped' : fn(op), k);
const codeOf = (s) => {
  if (!s) return null;
  if (s.startsWith('This step was skipped')) return 'skipped';
  if (CODE_OF.has(s)) return CODE_OF.get(s);
  if (/^The two shapes overlap by less than/.test(s)) return 'sliver';
  if (/works on shapes, but argument/.test(s)) return 'interpreterArg';
  if (/needs two or more shapes: /.test(s)) return 'interpreter';
  return '?';
};
const GCODE = { sameShape: 'G1', hangCross: 'G2', hangCone: 'G2', hangTorus: 'G2', sliver: 'G3', cutNothing: 'G4', cutNothingThin: 'G4b', keepNothing: 'G5', keepNothingKernel: 'K1', pinchJoin: 'G6', pinchCut: 'G7', tangentCircle: 'G13', hollowBall: 'G14', tubeTool: 'G10', cutEverything: 'K2', curvedKernel: 'K9', needTwo: 'K5', consumed: 'K6', skipped: 'K7', generic: 'K0', trap: 'K8', budget: 'budget', pieces: 'G12', interpreter: 'interpreter', interpreterArg: 'interpreter+G15' };

const cG = new Map(); for (const [id, r] of guarded) cG.set(id, { ...classify(r), row: r });
const cS = new Map(); for (const [id, r] of shipped) cS.set(id, { ...classify(r), row: r });
const cU = new Map(); for (const [id, r] of unguarded) cU.set(id, { ...classify(r), row: r });
const RANK = { supported: 0, refused: 1, unsupported: 2, wrong: 3 };
const secs = (id) => { const t = timing.get(id); return t && t.result === 'done' ? `${(t.scRunMs / 1000).toFixed(1)} s` : t ? `no result in ${t.limitS} s` : null; };

const CMD_G = 'SOLIDCRAFT_REFEREE_PKG=<pkg dir from RIG.md> booleans-r3/run-r3.sh guarded <the case ids listed> 150 <absolute outdir>   (= BOOL_TR=guarded systemd-run --user --scope -p MemoryMax=16G -p MemorySwapMax=0 bun docs/spikes/solidcraft-referee/contract/run-booleans.mjs --all --only=<ids> --timeout=150)';
const CMD_S = 'same with BOOL_TR=phase0 (the pristine phase0 translator); one case: BOOL_TR=phase0 bun .../run-booleans.mjs --case=<id>';
const CMD_U = 'same with BOOL_TR=r3raw (executor, no guard)';

const needShipped = new Set();
const fails = [];
const fail = (m) => { fails.push(m); console.error('ASSERT:', m); };
const rows = [];
const byNo = new Map();
const meta = new Map();   // key -> {ops:[], cat:[]}

const cpuNote = (g) => { const fr = g.row.finalRun; return fr && fr.cpuMs >= 3000 ? `, one sc.run of the final list ${(fr.cpuMs / 1000).toFixed(1)} s cpu (${(fr.wallMs / 1000).toFixed(1)} s wall, load ${fr.load1})` : ''; };
function gLine(id) {
  const g = cG.get(id); if (!g) { fail(`no guarded result for ${id}`); return `${id}: NO GUARDED RESULT`; }
  if (g.status === 'refused') { const code = GCODE[codeOf(g.sentence)] ?? '?'; return `${id}: refused [${code}] "${g.sentence}"`; }
  return `${shortOf(g.row, g)}${cpuNote(g)}${g.flags?.length ? ` {${g.flags.join(', ')}}` : ''}`;
}
function otherLine(map, id, label) {
  const s = map.get(id); if (!s) return `${id}: (not run ${label})`;
  const t = secs(id);
  if (s.status === 'refused') return `${id}: refused "${String(s.sentence).slice(0, 330)}"`;
  if (s.status === 'unsupported') return `${id}: no result within ${s.row.timeoutMs / 1000} s (stage ${s.row.lastStage})${t ? `; a longer run returned after ${t}` : ''}`;
  return `${shortOf(s.row, s)}${t ? `, one sc.run ${t}` : ''}${s.flags?.length ? ` {${s.flags.join(', ')}}` : ''}`;
}
/** one contract row from cases: expect = the status of EVERY case with the guard in front */
function row(no, feature, ids, expect, { note = '', raw = 'differs', ung = 'differs', sentence, ops = [], cat = [], solids = false } = {}) {
  if (solids) for (const id of ids) { const r = cG.get(id)?.row; if (!r?.truck || !r?.occt || r.truck.bodies !== r.occt.solids) fail(`row ${no}: solid count differs from OCCT for ${id}: SolidCraft ${r?.truck?.bodies} vs OCCT ${r?.occt?.solids}`); }
  const gs = ids.map((id) => cG.get(id)?.status ?? 'missing');
  const bad = ids.filter((id, i) => gs[i] !== expect);
  if (bad.length) fail(`row ${no} "${feature.slice(0, 50)}": expected ${expect} for every case, got ${bad.map((id) => `${id}=${cG.get(id)?.status}`).join(', ')}`);
  const refused = ids.map((id) => cG.get(id)).filter((c) => c?.status === 'refused');
  const sentences = [...new Set(refused.map((c) => c.sentence))];
  const frontEnd = new Set(ids.filter((id) => cG.get(id)?.row?.outcome === 'REFUSED-FRONT' && !cG.get(id)?.row?.interpreterRaw).map((id) => cG.get(id).sentence));   // the interpreter's own text (packages/script is read-only here)
  for (const s of sentences) { if (/needs two or more shapes: /.test(s) || frontEnd.has(s)) continue; const l = GD.lintSentence(s); if (l.length) fail(`row ${no}: sentence lint ${l.join('; ')}: ${s}`); }
  const tally = Object.entries(gs.reduce((a, s) => { a[s] = (a[s] ?? 0) + 1; return a; }, {})).map(([k, v]) => `${k} ${v}`).join(', ');
  const differs = (m, id) => m.get(id) && (m.get(id).status !== cG.get(id)?.status || (m.get(id).status === 'refused' && m.get(id).sentence !== cG.get(id)?.sentence));
  if (raw === 'all') for (const id of ids) if (!cS.has(id)) needShipped.add(id);
  const showRaw = ids.filter((id) => raw === 'all' ? cS.has(id) : raw === 'differs' && differs(cS, id));
  const showUng = ids.filter((id) => ung === 'all' ? cU.has(id) : ung === 'differs' && differs(cU, id) && !showRaw.includes(id));
  const out = {
    feature, status: expect,
    ...(expect === 'refused' ? { refusalSentence: sentence ?? sentences[0] } : {}),
    evidence: `${expect === 'wrong' ? 'WRONG SOLID OR TOPOLOGY. ' : ''}cases (${ids.length}), with the guard in front: ${tally}. ${note}${sentences.length > 1 ? ` ${sentences.length} distinct sentences (one per operation wording or per guard), each quoted on its case line.` : ''}\n`
      + `Command: ${CMD_G}\n`
      + `Measured with the guard (BOOL_TR=guarded):\n${ids.map((id) => '  ' + gLine(id)).join('\n')}`
      + (showUng.length ? `\nWithout the guard, executor only (${CMD_U}):\n${showUng.map((id) => '  ' + otherLine(cU, id, 'unguarded')).join('\n')}` : '')
      + (showRaw.length ? `\nAs shipped (${CMD_S}):\n${showRaw.map((id) => '  ' + otherLine(cS, id, 'as shipped')).join('\n')}` : ''),
  };
  // ROUND 4: a 'wrong' row whose cases all agree with OCCT on volume, area, bounding box, centre of mass and shell count and differ ONLY in how the faces are grouped is TOPOLOGY-ONLY; roll-ups name it instead of calling the whole operation wrong
  const topo = expect === 'wrong' && ids.every((id) => cG.get(id)?.flags?.includes('topology-only: geometry agrees'));
  out.__key = String(no); rows.push(out); byNo.set(String(no), out); meta.set(String(no), { ops, cat, topo }); return out;
}
/** a row backed by something other than run-booleans cases */
function manual(no, feature, status, sentence, evidence, { ops = [], cat = [] } = {}) {
  if (status === 'refused' && GD.lintSentence(sentence).length) fail(`manual row ${no} sentence lint ${GD.lintSentence(sentence)}`);
  const out = { feature, status, ...(status === 'refused' ? { refusalSentence: sentence } : {}), evidence }; out.__key = String(no); rows.push(out); byNo.set(String(no), out); meta.set(String(no), { ops, cat }); return out;
}
const J = ['join'], C = ['cut'], K = ['keep'], JC = ['join', 'cut'], JCK = ['join', 'cut', 'keep'], CK = ['cut', 'keep'];

// ============================================================ the rows ==========================================================
const NR = 5; for (let i = 0; i < NR; i++) rows.push(null);   // rows 1-5 are roll-ups, filled in at the end (they keep the numbers the critic used)
// ---- join -------------------------------------------------------------------------------------------------------------------
row(6, 'join(a,b): box + cylinder (through the box, straddling a face)', ['join-box-cyl-through', 'join-box-cyl-sideways-overlap'], 'supported', { ops: J, cat: ['operand'] });
row(7, 'join(a,b,c,...) with three or four operands (targets[2+])', ['join-three', 'join-four', 'join-bridge'], 'supported', { note: 'join(a,c,b) where only the 3rd operand bridges two disjoint solids is one solid, 1 shell.', ops: J, cat: ['operand'] });
row(8, 'join with a pull() operand (boss on a plate, sunk boss, round boss)', ['join-pull-boss', 'join-pull-sunk', 'join-pull-circle'], 'supported', { ops: J, cat: ['operand'] });
row(9, 'join with a spin() operand (solid profile, half turn, ring profile through the part)', ['join-spin', 'sp-join-solid-180', 'sp-join-tube-360'], 'supported', { ops: J, cat: ['operand'] });
row(10, 'join with a hole() result operand (boss beside the hole, boss that closes the hole into an internal void)', ['join-hole-boss', 'join-hole-cover'], 'supported', { ops: J, cat: ['operand'] });
row(11, 'join / cut / keep of an earlier combine result (join(join(a,b),c), cut(join(a,b),c), cut(cut(a,b),c), keep(cut(a,b),c), keep(keep(...),c))', ['join-chain', 'cut-of-join', 'cut-of-cut', 'keep-of-cut', 'keep-chain'], 'supported', { ops: JCK, cat: ['operand'] });
// ---- cut --------------------------------------------------------------------------------------------------------------------
row(12, 'cut(a,b): box - cylinder (through, blind from the top face, cylinder entirely inside = internal void)', ['cut-box-cyl-through', 'cut-box-cyl-blind', 'cut-box-cyl-inside'], 'supported', { ops: C, cat: ['operand'] });
row(13, 'cut(a,b,c,...): target plus two or three tools (targets[2+])', ['cut-three', 'cut-four'], 'supported', { note: 'Equal to a left fold a-b-c.', ops: C, cat: ['operand'] });
row(14, 'cut with a pull() operand', ['cut-pull-slot'], 'supported', { ops: C, cat: ['operand'] });
row(15, 'cut with a spin() operand whose profile touches the axis (solid bore, half turn, cone void), or a ring-profile (tube) tool wholly inside the part (full or half turn)', ['cut-spin-bore', 'cut-spin-cone-groove', 'sp-cut-solid-180', 'sp-cut-tube-void', 'r3-ring-cut-180-void', 'r3-ring-cut-through-cyl-core'], 'supported', { ops: C, cat: ['operand'] });
row('15b', 'cut with a spin() operand whose profile is a ring (tube) and passes through the part (full turn and half turn)', ['sp-cut-tube-360-through', 'sp-cut-tube-180-through'], 'refused', { raw: 'all', note: 'Round 2 left these as a silent WRONG solid: volume, bbox and COM agree with OCCT but the area is 7.5 % (full turn) and 4.0 % (half turn) larger, the tool\'s inner wall survives as an extra internal surface and the core that OCCT returns as a second solid is not separated. G10 now refuses a tube tool that is not wholly inside the part, before any kernel call.', ops: C, cat: ['operand'] });
row('15c', 'cut with a spin() operand whose profile is a ring (tube) and ends inside the part (blind tube)', ['sp-cut-tube-360-blind'], 'refused', { raw: 'all', note: 'SolidCraft refuses it with kernel text (curved tool faces, "planar faces only"); G10 refuses it first with a sentence that names the tube tool, not a false cause.', ops: C, cat: ['operand'] });
row('15d', 'a spin() tube as the TARGET of a cut or keep (a slab cut through a tube; a box keeping a tube)', ['r3-ring-target-cut-box', 'r3-ring-target-keep-box'], 'supported', { ops: CK, cat: ['operand'] });
row(16, 'cut with a hole() result operand (holed plate as target; holed plate as the TOOL)', ['cut-hole-target', 'cut-hole-as-tool'], 'supported', { ops: C, cat: ['operand'] });
// ---- results that fall into several pieces ------------------------------------------------------------------------------------------------
row(17, 'result with more than one solid: a cut or keep that separates the part (slot through a plate, two crossing slabs = four corner blocks, slit through a disc, eight corner blocks of a box cut by a big ball, keep of two separate cylinders)', ['split-cut-slot-two-pieces', 'split-cut-ring-pieces', 'split-keep-two-pieces', 'r3-split-slot', 'r3-split-cross4', 'r3-split-boxbox-small', 'r3-split-ball-corners', 'r3-split-cyl-bar', 'r3-split-keep-two-cyl'], 'supported', { raw: 'all', note: 'FIXED in round 3 (round 2: wrong, the student saw half the part). booleans-r3/combine-exec.mjs collects every body a combine produces: SolidCraft names the extra solids "<name> (1)", "<name> (2)" and the pristine translator kept only the one that kept the target\'s name. Solid counts equal OCCT\'s in every case (asserted by this script; the "solids O/T" field of the case JSON).', ops: CK, cat: ['pieces'], solids: true });
row('17b', 'cut of a cone by a slab through its axis (two half cones)', ['r3-split-cone-slab'], 'refused', { raw: 'all', note: 'The kernel refuses it ("coincident faces were left in place"): the slab\'s faces meet the cone along its axis. The critic\'s cone-box repro gave 1.34 against 4235.7 with one body as shipped; with the executor it is a plain refusal here, not a wrong solid.', ops: C, cat: ['pieces'] });
row(18, 'operating on a handle that is several pieces after a cut split it: a cut or join aimed at one piece, at both, at a re-split piece, a keep, a join that bridges the pieces, a handle used as the TOOL of a cut or keep, an n-ary cut', ['split-then-cut-other-piece', 'split-then-join-other-piece', 'r3-split-then-cut-other', 'r3-split-then-cut-both', 'r3-split-then-join-other', 'r3-split-bridge', 'r3-split-keep-after', 'r3-split-resplit', 'r3-split-as-tool', 'r3-split-as-keep-tool', 'r3-split-cut3-pieces'], 'supported', { raw: 'all', note: 'FIXED in round 3 (round 2: wrong). A multi-piece handle is combined piece by piece, the tool kept alive (keep_tools) until the last piece: probe-pieces.txt shows that a cut or intersect of a piece the tool does not touch is a clean no-op / vanish, not an error. join(pieces..., x) fuses the pieces of its first operand into one body (r3-split-then-join-other: one body with 2 shells where OCCT lists 2 solids, same shells and volume, the convention of the disjoint-union row); a bridge across the slot makes ONE solid (OCCT 1, SolidCraft 1).', ops: JCK, cat: ['pieces'] });
row('18b', 'a step that is NOT a combine (hole, pocket, shell, fillet...) handed the pieces of an earlier cut', ['r3-split-then-hole'], 'refused', { raw: 'all', note: 'Every non-combine step of the translator needs one body ("needs a single ... body"); the pristine text is developer text, replaced by G12. The sentence belongs to this group because the pieces come from a combine.', ops: [], cat: ['pieces'] });
// ---- keep -------------------------------------------------------------------------------------------------------------------
row(19, 'keep(a,b): two operands (box & cylinder, & pull, & spin incl. ring profile, & holed plate)', ['keep-box-cyl', 'keep-box-cyl-clip', 'keep-pull', 'keep-spin', 'keep-hole-target', 'sp-keep-tube-360', 'sp-keep-tube-180'], 'supported', { ops: K, cat: ['operand'] });
row(20, 'keep(a,b,c,...): three or more operands (targets[2+])', ['keep-three', 'keep-three-sph', 'keep-four', 'r3-keep-apq', 'r3-keep-four-boxes', 'r3-keep-three-cyl', 'r3-keep-split-first', 'r3-keep-split-first-lost'], 'supported', { raw: 'all', note: 'FIXED in round 3 (round 2: wrong). Root cause measured with SolidCraft alone (probe-nary-intersect.mjs): an n-ary solid.combine intersect is target & (union of the tools), not the intersection of all of them (slabs A,P,Q: n-ary 24000, closed form 8000). The executor emits one intersect per tool operand, in order, and combines every piece a step leaves; r3-keep-split-first has a&d in two pieces and then &e acting on BOTH.', ops: K, cat: ['operand'] });
row('20b', 'keep(a,b,c) whose three operands have nothing in common although pairs of them overlap', ['r3-keep-slabs-empty'], 'refused', { raw: 'all', note: 'The n-ary form wrongly returned 2000 (a & (b or c)) as shipped; now nothing is left and the sentence says so.', ops: K, cat: ['operand'] });
// ---- arity, handles, reuse --------------------------------------------------------------------------------------------------
row(21, 'same handle twice: join(a, a) / cut(a, a) / keep(a, a) / join(a, b, a)', ['arity-join-same-twice', 'arity-cut-same-twice', 'sh-keep-a-a', 'sh-join-a-a-b'], 'refused', { raw: 'all', note: 'G1 refuses before the kernel is called. The sentence names no id.', ops: JCK, cat: ['arity'] });
row('21b', 'fewer than two shapes: join(), cut(), keep() with no argument or one shape', ['arity-join-one', 'arity-cut-one', 'arity-keep-one', 'arity-join-zero'], 'refused', { raw: 'all', note: 'These sentences come from the interpreter (runScript), no kernel involved. They are right for fewer than two arguments; for two arguments with a wrong kind see the next row.', ops: JCK, cat: ['arity'] });
row('21c', 'two or more arguments but one is not a shape: cut(a, 5), join(a, \'b\'), keep(5, a), keep(a, aSketch), cut(a, aSketch), join(a, b, 7), cut(a, [1,2])', ['arity-cut-number', 'arity-keep-sketch', 'r3-arity-cut-number', 'r3-arity-join-text', 'r3-arity-keep-first-number', 'r3-arity-cut-sketch-second', 'r3-arity-join-three-one-bad', 'r3-arity-cut-point-list', 'r3-arity-cut-unknown-name'], 'refused', { raw: 'none', ung: 'none', note: 'The interpreter says "cut() needs two or more shapes: cut(a, b)." for cut(a, 5) although two arguments were given (round 2 critic). packages/script is read-only here, so the contract is a page-side rewrite: booleans.guard.mjs explainCombineArgs(message, source, line) reads the failing call from the script text and names the argument and its kind (a number, text, a list, a sketch). It returns null for fewer than two arguments, where the interpreter\'s message is right. A name that is not defined (cut(a, nothing)) already gets the interpreter\'s own sentence "nothing is not a tool here. Did you mean ring()?" (r3-arity-cut-unknown-name).', ops: JCK, cat: ['arity'] });
row(22, 'combine with a single target written directly in a ModelDoc (bypassing the interpreter)', ['arity-modeldoc-one-target'], 'refused', { raw: 'all', note: 'Round 1 sentence was "op1 (combine): needs two or more targets"; now a student sentence.', ops: JCK, cat: ['arity'] });
row('23a', 'a tool used again after a combine consumed it, planar tool (one cutter slot through two separate plates; a shape that is a target of one combine after being a tool of another)', ['reuse-box-tool-two-plates', 'reuse-box-tool-keep', 'reuse-tool-first-arg'], 'supported', { raw: 'all', note: 'SolidCraft has keep_tools on solid.combine; the contract translator emits keep_tools:true for the tools a LATER feature still uses. Raw probe (bool-keep-tools-probe.mjs): cutting one cylinder from two plates with keep_tools:true built both plates, 14869.215 mm3 each (closed form 14869.027, tessellation d 1.3e-5); without keep_tools the second use fails with "unknown body `t`".', ops: JCK, cat: ['reuse'] });
row('23b', 'a round tool used again after a combine consumed it (one long cylinder through two separate plates; a cylinder shared by two overlapping plates, for cut and for keep)', ['reuse-round-tool-disjoint', 'reuse-tool-join-two', 'reuse-tool-keep-pair'], 'supported', { raw: 'all', note: 'keep_tools works for round tools too.', ops: JCK, cat: ['reuse'] });
row('23c', 'a round tool shared by overlapping plates: the volume agrees but the cylinder face count does not', ['reuse-tool-two-tools', 'reuse-tool-three-parts', 'reuse-ctl-cyl-two-tools'], 'wrong', { raw: 'all', note: 'Face census only (volume, area, bbox, COM, shell count agree). The control reuse-ctl-cyl-two-tools builds the same model with a second identical cylinder instead of reuse and has the same face counts, so keep_tools is not the cause: it is how SolidCraft splits the bore wall where two plates that share a bore are joined (5 cylinder faces against OCCT 6 and 2 edge-connected components). Counted as wrong under the same rule the sphere-sphere row uses; no guard exists that tells this case from a good join without the face census itself.', ops: JC, cat: ['reuse'] });
row('23d', 'a tool reused by a second combine that touches nothing (the round-1 reuse-tool-twice script: the second plate is 60 mm away from the cutter)', ['reuse-tool-twice'], 'refused', { raw: 'all', note: 'POLICY refusal (see the disjoint-cut row): with keep_tools the first cut is fine and the SECOND cut touches nothing, so G4 refuses it and the join after it is skipped.', ops: C, cat: ['reuse'] });
row('23e', 'a shape used as a TARGET again after an earlier combine changed it in place (cut(a,c) after join(a,b))', ['reuse-target-after-union'], 'refused', { raw: 'all', note: 'Still refused: a target is changed in place and keep_tools only protects tools. solid.move has copy:true; the copy would have to be made BEFORE the first combine and its generated name tracked, which was not built or measured here, so a second copy of the shape (a second box(...) call) is what the sentence asks for.', ops: JCK, cat: ['reuse'] });
// ---- curved -----------------------------------------------------------------------------------------------------------------
row(24, 'curved: cylinder in box with a rotated (x) axis: cut, join, keep', ['x-cut-x-axis-cylinder', 'x-join-x-axis-cylinder', 'x-keep-x-axis-cylinder'], 'supported', { ops: JCK, cat: ['curved'] });
